export function applyRecordingLinks(words){for(const w of words){const link=recordingLinks[w.id];if(!link)continue;if(!w.audio&&link.audio)w.audio=link.audio;for(const e of [...(w.examples||[]),...(w.teachingExamples||[])])if(!e.audio&&link.examples[e.de])e.audio=link.examples[e.de]}}

export function applyClozeRecordingLinks(items){for(const item of items){const audio=recordingLinks[item.wordId]?.examples?.[item.sentence];if(!item.audio&&audio)item.audio=audio}}
